SELECT 
FROM care_plan_task_checkin
WHERE task_id = #{taskId}
  AND checkin_date = #{checkinDate}
  AND time_slot = #{timeSlot}
  AND is_deleted = 0
LIMIT 1

SELECT 
FROM care_plan_task_checkin
WHERE tenant_id = #{tenantId}
  AND people_id = #{peopleId}
  AND checkin_date = #{checkinDate}
  AND is_deleted = 0
ORDER BY task_id, time_slot

